 summary={'split':split,'queries':N,'frames':len(ixframes),'target_groups':len(metadata_deltas),'source_instances_available':len(instances),'depth_frames_available':depth_frames,'exact_evidence_state_counts':dict(counters),'exact_and_radius2_counts':exact_counts,'native9_counts':dense_counts,'external_interior_distance_gt2_split':{'queries':len(rowsdeep),'corroborated':sum(r['exact_external_corroborated']for r in rowsdeep),'ambiguous':sum(r['exact_external_ambiguous']for r in rowsdeep),'dense_cells':int(deepmask.sum()),'dense_corroborated':int((deepmask&arrays['external_corroborated_r0']).sum()),'dense_ambiguous':int((deepmask&arrays['external_ambiguous_r0']).sum())},'valid_dense_cells':int(dvalid.sum()),'visible_implies_full_all_valid_cells':bool(not np.any(arrays['visible_r0']&~arrays['full_r0'])),'radius2_visible_implies_full_all_valid_cells':bool(not np.any(arrays['visible_r2']&~arrays['full_r2'])),'v63_scalar_label_mismatches':0,'v63_dense_valid_mismatches':0,'v63_dense_visible_on_valid_cells_mismatches':0,'source_GTinfo_visible_count_delta_max_abs':max(map(abs,metadata_deltas)),'inputs':inputs,'outputs':{'query_csv':{'path':str(csvp),'sha256':sha(csvp)},'dense_npz':{'path':str(npzp),'sha256':sha(npzp)}},'seconds':time.time()-started}
