 (OUT/'YCB_EVIDENCE_AUDIT_SCHEMA.json').write_text(json.dumps({'query_join_key':'sample_id','dense_join_key':'sample_id','query_CSV_fields':'see CSV header','dense_arrays':{'visible_r0':'native9 exact visible mask bool','full_r0':'native9 exact target full mask bool','visible_r2':'native9 clipped5x5 any visible bool','full_r2':'native9 clipped5x5 any full bool','valid':'continuous and rounded-pixel native bounds; mask all losses with this','external_corroborated_r0':'full1vis0 & other-instancevisible1','external_ambiguous_r0':'full1vis0 & other-instancevisible0','other_visible_r0':'union of all other source annotated instance visible masks','strict_external_corroborated_5x5':'whole25px full1vis0other1','enclosed_void_r0':'2D enclosed full-mask background component','depth_mm':'observed depth mm, invalid grid=NaN; depth_missing marks0/absent','visible_signed_distance_px':'inside distance minus outside distance; invalid=NaN','full_signed_distance_px':'inside distance minus outside distance; invalid=NaN'},'all_other_bool_array_names':'documented in fixed protocol and summary counts'},indent=2));print('SOURCE AUDIT COMPLETE',flush=True)
